  var DIFF = 'normal';
  var MODE = 'download';        // download | fun
  var CURRENT = null;
  var CLEANUP = null;
  var LAST_ID = '';
  var RESULTED = false;
  var FORCED = '';
  var LEVEL = 0;                 // 0 = 走难度档；1-10 = 走关卡
  var STYLE = '';                // 打地鼠专用：'mole' 地鼠关 / 'text' 文字关

  var homeEl = document.getElementById('home');
  var gameEl = document.getElementById('gameview');
  var stage = document.getElementById('stage');
  var ov = document.getElementById('ov');
  var card = document.getElementById('card');
  var toastEl = document.getElementById('toast');
  var hudEl = document.getElementById('hud');
  var gName = document.getElementById('gName');
  var gMeta = document.getElementById('gMeta');
  var hintEl = document.getElementById('stagehint');

  var DIFF_LABEL = { easy: '简单', normal: '普通', hard: '困难' };

  /* ---------- 小工具 ---------- */
  function el(tag, cls, txt) {
    var e = document.createElement(tag);
    if (cls) e.className = cls;
    if (txt !== undefined) e.textContent = txt;
    return e;
  }
  function rand(n) { return Math.floor(Math.random() * n); }
  function pickDiff(obj) { return obj[DIFF] || obj.normal; }
  function fmtTime(sec) {
    var s = Math.max(0, sec), m = Math.floor(s / 60), r = s % 60;
    return m + ':' + (r < 10 ? '0' + r : r);
  }
  function clearStage() {
    if (CLEANUP) { try { CLEANUP(); } catch (e) {} CLEANUP = null; }
    while (stage.firstChild) stage.removeChild(stage.firstChild);
    while (hudEl.firstChild) hudEl.removeChild(hudEl.firstChild);
    hintEl.textContent = '';
    ov.hidden = true;
    toastEl.classList.remove('on');
  }
  function hudChip(k, v) {
    var c = el('div', 'chip');
    var ks = el('span', 'k', k);
    var vs = el('span', 'v', v);
    c.appendChild(ks); c.appendChild(vs);
    hudEl.appendChild(c);
    return vs;
  }
  function toast(msg) {
    toastEl.textContent = msg;
    toastEl.classList.add('on');
    clearTimeout(toastEl._t);
    toastEl._t = setTimeout(function () { toastEl.classList.remove('on'); }, 1600);
  }

  function fmtBytes(n) {
    if (n < 1024) return n + ' B';
    if (n < 1048576) return (n / 1024).toFixed(1).replace('.0', '') + ' KB';
    return (n / 1048576).toFixed(2) + ' MB';
  }
  function docxSize() {
    var p = DOCX_B64.slice(-2) === '==' ? 2 : (DOCX_B64.slice(-1) === '=' ? 1 : 0);
    return Math.floor(DOCX_B64.length * 3 / 4) - p;
  }
  function downloadDocx() {
    try {
      var bin = atob(DOCX_B64);
      var bytes = new Uint8Array(bin.length);
      for (var i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
      var blob = new Blob([bytes], { type: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' });
      var url = URL.createObjectURL(blob);
      var a = el('a');
      a.href = url;
      a.download = DOCX_NAME;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      setTimeout(function () { URL.revokeObjectURL(url); }, 6000);
      return true;
    } catch (e) {
      return false;
    }
  }

  /* ---------- 结果卡 ---------- */
  function showResult(kind) {
    RESULTED = true;
    var again = el('button', 'btn');
    var back = el('button', 'btn ghost', '回首页');
    var body;
    if (kind === 'win') {
      if (MODE === 'download') {
        var ok = downloadDocx();
        body = '<span class="stamp">已解锁</span><h2>通关，文件开始下载</h2>' +
          '<p class="note">' + (ok ? '已经自动把「' + DOCX_NAME + '」推给浏览器了，看下载栏即可。' :
            '自动下载被浏览器拦了，请换电脑端 Chrome / Edge 打开本文件再试。') +
          '</p>';
        again.textContent = '再抽一个玩';
      } else {
        body = '<span class="stamp">通关</span><h2>这局过了</h2>' +
          '<p class="note">纯娱乐模式，不涉及文件。想换关卡就回首页挑。</p>';
        again.textContent = '再来一局';
      }
    } else {
      body = '<span class="stamp" style="color:#c4693f;border-color:#7a422c">没过</span>' +
        '<h2>这局没扛住</h2>' +
        '<p class="note">封条还没拆开。要么重来一局，要么回首页换条路。</p>';
      again.textContent = '重来一局';
    }
    card.innerHTML = body;
    card.appendChild(again);
    card.appendChild(back);
    ov.hidden = false;
    again.addEventListener('click', function () {
      if (kind === 'win' && MODE === 'download') startGame(true);
      else startGame(false);
    });
    back.addEventListener('click', goHome);
  }

  /* ---------- 开局 / 首页 ---------- */
  function goHome() {
    clearStage();
    gameEl.hidden = true;
    homeEl.hidden = false;
    RESULTED = false;
    CURRENT = null;
  }

  function chooseGame() {
    if (FORCED) {
      for (var f = 0; f < GAMES.length; f++) if (GAMES[f].id === FORCED) return GAMES[f];
    }
    var pool = GAMES.filter(function (g) { return g.id !== LAST_ID; });
    if (!pool.length) pool = GAMES;
    return pool[rand(pool.length)];
  }

  function startGame(reroll) {
    RESULTED = false;
    clearStage();
    homeEl.hidden = true;
    gameEl.hidden = false;

    var g = reroll ? chooseGame() : (CURRENT || chooseGame());
    CURRENT = g;
    LAST_ID = g.id;

    gName.textContent = g.name;
    gMeta.textContent = (MODE === 'download' ? (FORCED ? '下载模式 · 指定玩法' : '下载模式 · 随机抽到') : '纯娱乐 · ') + DIFF_LABEL[DIFF];
    if (LEVEL) {
      gMeta.textContent = '第 ' + LEVEL + ' 关' + (CURRENT.id === 'mole' ? (STYLE === 'mole' ? ' · 地鼠关' : ' · 文字关') : '')
        + ' / 共 10 关';
    }
    hintEl.textContent = g.hint || '';

    var api = {
      diff: DIFF,
      level: LEVEL,
      style: STYLE,
      win: function () { if (!RESULTED) showResult('win'); },
      lose: function () { if (!RESULTED) showResult('lose'); },
      toast: toast,
      hud: hudChip
    };

    CLEANUP = g.start(stage, api) || null;
  }

  function showHall(on) {
    var dl = document.getElementById('dlBlock');
    var hb = document.getElementById('hallBlock');
    if (dl) dl.hidden = on;
    if (hb) hb.hidden = !on;
    var gc = document.getElementById('gameCount');
    if (gc) gc.textContent = on ? '16' : '15';
  }
  document.getElementById('btnDownload').addEventListener('click', function () {
    var mask = document.getElementById('askMask');
    if (mask) mask.hidden = false;
    var ok = document.getElementById('btnOkay');
    if (ok && ok.focus) ok.focus();
  });
  document.getElementById('btnOkay').addEventListener('click', function () {
    var mask = document.getElementById('askMask');
    if (mask) mask.hidden = true;
    showHall(true);
    var hb = document.getElementById('hallBlock');
    if (hb && hb.scrollIntoView) hb.scrollIntoView({block: 'start'});
  });
  document.getElementById('btnRestart').addEventListener('click', function () {
    startGame(false);
  });
  document.getElementById('btnHome').addEventListener('click', function () {
    goHome();
    showHall(false);
  });

  function buildPick(boxId, onPick) {
    var box = document.getElementById(boxId);
    if (!box) return;
    GAMES.forEach(function (g) {
      var b = el('button', 'hallcard', '');
      b.type = 'button';
      var th = el('span', 'hallthumb');
      th.innerHTML = THUMBS[g.id] || THUMBS._default;
      b.appendChild(th);
      var meta = el('span', 'hallmeta');
      meta.appendChild(el('b', '', g.name));
      meta.appendChild(el('small', '', g.hint || ''));
      b.appendChild(meta);
      b.setAttribute('data-gid', g.id);
      b.addEventListener('click', function () { onPick(g.id); });
      box.appendChild(b);
    });
  }


  /* ==========================================================
     共用小工具
     ========================================================== */
  function newCanvas(root, w, h) {
    var c = el('canvas', 'cv');
    c.width = w; c.height = h;
    root.appendChild(c);
    return c;
  }
  function rafLoop(fn) {
    var id = 0, last = 0, running = true;
    function frame(t) {
      if (!running) return;
      if (!last) last = t;
      var dt = Math.min(0.05, (t - last) / 1000);
      last = t;
      fn(dt);
      id = requestAnimationFrame(frame);
    }
    id = requestAnimationFrame(frame);
    return function () { running = false; cancelAnimationFrame(id); };
  }

  /* ==========================================================
     1. 击破封条（打砖块）
     ========================================================== */
  GAMES.push({
    id: 'brick',
    name: '打砖块',
    hint: '左右移动挡板把球弹回去，把整面砖打光。可以用鼠标、手指或左右方向键控制。',
    start: function (root, api) {
      /* 关卡 1-10 的参数，数字直接改这里 */
      var LV = [
        { cols: 8, rows: 3, lives: 5, speed: 320 },
        { cols: 9, rows: 3, lives: 5, speed: 340 },
        { cols: 9, rows: 4, lives: 4, speed: 360 },
        { cols: 10, rows: 4, lives: 4, speed: 380 },
        { cols: 10, rows: 4, lives: 3, speed: 400 },
        { cols: 10, rows: 5, lives: 3, speed: 415 },
        { cols: 10, rows: 5, lives: 3, speed: 430 },
        { cols: 10, rows: 6, lives: 2, speed: 445 },
        { cols: 10, rows: 6, lives: 2, speed: 460 },
        { cols: 10, rows: 6, lives: 2, speed: 470 }
      ];
      var P = LV[api.level ? Math.min(9, Math.max(0, api.level - 1)) : (api.diff === 'easy' ? 0 : api.diff === 'hard' ? 9 : 4)];

      var PALETTE = ['#c4693f', '#c99a48', '#84995f', '#4f8fa0', '#7274a8', '#a15a68'];
      var W = 420, H = 520;
      var c = newCanvas(root, W, H);
      var g = c.getContext('2d');
      var livesV = api.hud('剩余球', String(P.lives));
      var leftV = api.hud('剩余砖块', '');

      var padW = 92, padH = 12, padX = (W - padW) / 2, padY = H - 32;
      var ball = { x: W / 2, y: padY - 18, r: 6, vx: 0, vy: 0 };
      var bricks = [];
      var gap = 6, top = 64, rowH = 22;
      var bw = (W - 40 - gap * (P.cols - 1)) / P.cols;
      var alive = 0;
      var lives = P.lives;
      var over = false;

      for (var r = 0; r < P.rows; r++) {
        for (var col = 0; col < P.cols; col++) {
          bricks.push({ x: 20 + col * (bw + gap), y: top + r * (rowH + gap), w: bw, h: rowH,
                        row: r, on: true });
          alive++;
        }
      }
      leftV.textContent = String(alive);

      function launch() {
        var ang = (Math.random() * 0.7 + 0.55) * Math.PI;
        var sp = P.speed;
        ball.x = padX + padW / 2;
        ball.y = padY - 18;
        ball.vx = Math.cos(ang) * sp * 0.85;
        ball.vy = -Math.abs(Math.sin(ang) * sp * 0.9) - sp * 0.25;
      }
      launch();

      function loseLife() {
        lives--;
        livesV.textContent = String(lives);
        if (lives <= 0) { over = true; api.lose(); return; }
        launch();
      }

      function draw() {
        g.fillStyle = '#0b1114';
        g.fillRect(0, 0, W, H);
        for (var i = 0; i < bricks.length; i++) {
          var b = bricks[i];
          if (!b.on) continue;
          g.fillStyle = PALETTE[b.row % PALETTE.length];
          g.fillRect(b.x, b.y, b.w, b.h);
          g.fillStyle = 'rgba(255,255,255,.16)';
          g.fillRect(b.x, b.y, b.w, 3);
          g.fillStyle = 'rgba(0,0,0,.22)';
          g.fillRect(b.x, b.y + b.h - 4, b.w, 4);
        }
        g.fillStyle = '#d8a24a';
        g.fillRect(padX, padY, padW, padH);
        g.beginPath();
        g.arc(ball.x, ball.y, ball.r, 0, Math.PI * 2);
        g.fill();
      }

      var off = rafLoop(function (dt) {
        if (over) return;
        ball.x += ball.vx * dt;
        ball.y += ball.vy * dt;

        if (ball.x < ball.r) { ball.x = ball.r; ball.vx = Math.abs(ball.vx); }
        if (ball.x > W - ball.r) { ball.x = W - ball.r; ball.vx = -Math.abs(ball.vx); }
        if (ball.y < ball.r) { ball.y = ball.r; ball.vy = Math.abs(ball.vy); }

        if (ball.y > padY - ball.r && ball.y < padY + padH + ball.r &&
            ball.x > padX - ball.r && ball.x < padX + padW + ball.r && ball.vy > 0) {
          ball.y = padY - ball.r;
          var rel = (ball.x - (padX + padW / 2)) / (padW / 2);
          var sp = Math.sqrt(ball.vx * ball.vx + ball.vy * ball.vy);
          ball.vx = rel * sp * 0.75;
          ball.vy = -Math.abs(sp * 0.9);
        }

        for (var i = 0; i < bricks.length; i++) {
          var b = bricks[i];
          if (!b.on) continue;
          if (ball.x > b.x - ball.r && ball.x < b.x + b.w + ball.r &&
              ball.y > b.y - ball.r && ball.y < b.y + b.h + ball.r) {
            b.on = false;
            alive--;
            leftV.textContent = String(alive);
            if (Math.abs(ball.x - (b.x + b.w / 2)) / b.w > Math.abs(ball.y - (b.y + b.h / 2)) / b.h) {
              ball.vx = -ball.vx;
            } else {
              ball.vy = -ball.vy;
            }
            if (alive <= 0) { over = true; api.win(); return; }
            break;
          }
        }

        if (ball.y > H + 20) loseLife();
        draw();
      });

      function moveTo(clientX) {
        var rect = c.getBoundingClientRect();
        var x = (clientX - rect.left) / rect.width * W;
        padX = Math.max(0, Math.min(W - padW, x - padW / 2));
        if (ball.vx === 0 && ball.vy === 0) launch();
      }
      function onPointer(e) {
        if (e.touches && e.touches[0]) moveTo(e.touches[0].clientX);
        else moveTo(e.clientX);
      }
      c.addEventListener('pointermove', onPointer);
      c.addEventListener('pointerdown', onPointer);

      function onKey(e) {
        if (e.key === 'ArrowLeft') { padX = Math.max(0, padX - 26); e.preventDefault(); }
        if (e.key === 'ArrowRight') { padX = Math.min(W - padW, padX + 26); e.preventDefault(); }
      }
      window.addEventListener('keydown', onKey);

      return function () {
        off();
        window.removeEventListener('keydown', onKey);
        c.removeEventListener('pointermove', onPointer);
        c.removeEventListener('pointerdown', onPointer);
      };
    }
  });

  /* ==========================================================
     2. 果实封条（贪吃蛇）
     ========================================================== */
  GAMES.push({
    id: 'snake',
    name: '贪吃蛇',
    hint: '方向键或滑动转向，吃够果实就过关，撞墙撞自己就结束。',
    start: function (root, api) {
      /* 关卡 1-10 的参数，数字直接改这里 */
      var LV = [
        { target: 8, tick: 230 },
        { target: 10, tick: 225 },
        { target: 12, tick: 215 },
        { target: 13, tick: 195 },
        { target: 15, tick: 180 },
        { target: 16, tick: 172 },
        { target: 17, tick: 165 },
        { target: 18, tick: 158 },
        { target: 19, tick: 150 },
        { target: 20, tick: 145 }
      ];
      var P = LV[api.level ? Math.min(9, Math.max(0, api.level - 1)) : (api.diff === 'easy' ? 0 : api.diff === 'hard' ? 9 : 4)];

      var CELL = 20, COLS = 20, ROWS = 13;
      var W = CELL * COLS, H = CELL * ROWS;
      var c = newCanvas(root, W, H);
      var g = c.getContext('2d');
      var scoreV = api.hud('已吃', '0 / ' + P.target);

      var snake = [{ x: 6, y: 6 }, { x: 5, y: 6 }, { x: 4, y: 6 }];
      var dir = { x: 1, y: 0 }, nextDir = { x: 1, y: 0 }, food = null, over = false, eaten = 0;

      function placeFood() {
        do { food = { x: rand(COLS), y: rand(ROWS) }; }
        while (snake.some(function (s) { return s.x === food.x && s.y === food.y; }));
      }
      placeFood();

      function step() {
        if (over) return;
        dir = nextDir;
        var head = { x: snake[0].x + dir.x, y: snake[0].y + dir.y };
        if (head.x < 0 || head.x >= COLS || head.y < 0 || head.y >= ROWS) { over = true; api.lose(); return; }
        if (snake.some(function (s) { return s.x === head.x && s.y === head.y; })) { over = true; api.lose(); return; }
        snake.unshift(head);
        if (head.x === food.x && head.y === food.y) {
          eaten++;
          scoreV.textContent = eaten + ' / ' + P.target;
          if (eaten >= P.target) { over = true; api.win(); return; }
          placeFood();
        } else {
          snake.pop();
        }
        draw();
      }

      function draw() {
        g.fillStyle = '#0b1114';
        g.fillRect(0, 0, W, H);
        g.strokeStyle = '#1b2429';
        for (var i = 1; i < COLS; i++) { g.beginPath(); g.moveTo(i * CELL, 0); g.lineTo(i * CELL, H); g.stroke(); }
        for (var j = 1; j < ROWS; j++) { g.beginPath(); g.moveTo(0, j * CELL); g.lineTo(W, j * CELL); g.stroke(); }
        g.fillStyle = '#c4693f';
        g.beginPath();
        g.arc(food.x * CELL + CELL / 2, food.y * CELL + CELL / 2, CELL / 2 - 2, 0, Math.PI * 2);
        g.fill();
        for (var k = 0; k < snake.length; k++) {
          g.fillStyle = k === 0 ? '#d8a24a' : '#7d9c6a';
          g.fillRect(snake[k].x * CELL + 1, snake[k].y * CELL + 1, CELL - 2, CELL - 2);
        }
      }
      draw();

      var timer = setInterval(step, P.tick);

      function turn(x, y) {
        if (over) return;
        if (x === -dir.x && y === -dir.y) return;
        nextDir = { x: x, y: y };
      }
      function onKey(e) {
        if (e.key === 'ArrowLeft') { turn(-1, 0); e.preventDefault(); }
        if (e.key === 'ArrowRight') { turn(1, 0); e.preventDefault(); }
        if (e.key === 'ArrowUp') { turn(0, -1); e.preventDefault(); }
        if (e.key === 'ArrowDown') { turn(0, 1); e.preventDefault(); }
      }
      window.addEventListener('keydown', onKey);

      var sx = 0, sy = 0;
      c.addEventListener('pointerdown', function (e) { sx = e.clientX; sy = e.clientY; });
      c.addEventListener('pointerup', function (e) {
        var dx = e.clientX - sx, dy = e.clientY - sy;
        if (Math.abs(dx) < 18 && Math.abs(dy) < 18) return;
        if (Math.abs(dx) > Math.abs(dy)) turn(dx > 0 ? 1 : -1, 0);
        else turn(0, dy > 0 ? 1 : -1);
      });

      return function () {
        clearInterval(timer);
        window.removeEventListener('keydown', onKey);
      };
    }
  });

