  GAMES.push({
    id: 'g2048',
    name: '2048',
    hint: '方向键或下面的按键滑动，合出目标数字就过关。',
    start: function (root, api) {
      /* 关卡 1-10 的参数，数字直接改这里 */
      var LV = [
        { target: 64, four: 0.03 },
        { target: 128, four: 0.04 },
        { target: 192, four: 0.05 },
        { target: 256, four: 0.06 },
        { target: 512, four: 0.1 },
        { target: 768, four: 0.12 },
        { target: 1024, four: 0.15 },
        { target: 1536, four: 0.2 },
        { target: 2048, four: 0.24 },
        { target: 3072, four: 0.3 }
      ];
      var P = LV[api.level ? Math.min(9, Math.max(0, api.level - 1)) : (api.diff === 'easy' ? 0 : api.diff === 'hard' ? 9 : 4)];

      var TILE = {
        2: ['#303c43', '#dfe5e8'], 4: ['#3b4952', '#e8eaec'],
        8: ['#4d6656', '#eef1e9'], 16: ['#61793f', '#f2f4e7'],
        32: ['#84995f', '#161a0c'], 64: ['#a8792e', '#0f0c04'],
        128: ['#c99a48', '#13100a'], 256: ['#c4693f', '#f8ece6'],
        512: ['#d8a24a', '#171105'], 1024: ['#e6b25c', '#171105'],
        2048: ['#f0dfa8', '#171105'], 3072: ['#f6e7bd', '#171105'],
        4096: ['#fff3d6', '#171105']
      };
      var N = 4;
      var cells = [];
      var grid = el('div', 'n2048');
      root.appendChild(grid);
      for (var i = 0; i < N * N; i++) { var d = el('div', '', ''); grid.appendChild(d); cells.push(d); }

      var pad = el('div', 'padkeys');
      root.appendChild(pad);
      [['', '↑', ''], ['←', '↓', '→']].forEach(function (row) {
        row.forEach(function (k) {
          var b = el('button', '', k);
          if (!k) b.className = 'sp';
          b.disabled = !k;
          b.setAttribute('data-k', k);
          pad.appendChild(b);
        });
      });

      var board = [];
      for (var j = 0; j < N * N; j++) board.push(0);
      var maxV = api.hud('最大数', '0 / ' + P.target);
      var over = false;

      function addTile() {
        var empty = [];
        for (var k = 0; k < N * N; k++) if (!board[k]) empty.push(k);
        if (!empty.length) return;
        var at = empty[rand(empty.length)];
        board[at] = Math.random() < P.four ? 4 : 2;
      }

      function draw() {
        var maxv = 0;
        for (var k = 0; k < N * N; k++) {
          cells[k].textContent = board[k] ? String(board[k]) : '';
          var v = board[k];
          if (v > maxv) maxv = v;
          var spec = TILE[v] || ['#fff3d6', '#171105'];
          cells[k].style.background = v ? spec[0] : '#161e23';
          cells[k].style.borderColor = v ? 'rgba(255,255,255,.22)' : '#232c31';
          cells[k].style.color = v ? spec[1] : '#e8eaec';
          cells[k].style.fontWeight = v >= 128 ? '700' : '600';
        }
        maxV.textContent = maxv + ' / ' + P.target;
        if (maxv >= P.target && !over) { over = true; api.win(); }
      }

      function slide(dir) {
        if (over) return;
        var moved = false;
        for (var line = 0; line < N; line++) {
          var vals = [];
          for (var t = 0; t < N; t++) {
            var r = dir === 'up' ? t : (dir === 'down' ? N - 1 - t : line);
            var ccol = dir === 'left' ? t : (dir === 'right' ? N - 1 - t : line);
            var v = board[r * N + ccol];
            if (v) vals.push(v);
          }
          var out = [];
          for (var q = 0; q < vals.length; q++) {
            if (q + 1 < vals.length && vals[q] === vals[q + 1]) { out.push(vals[q] * 2); q++; }
            else out.push(vals[q]);
          }
          while (out.length < N) out.push(0);
          for (var t2 = 0; t2 < N; t2++) {
            var r2 = dir === 'up' ? t2 : (dir === 'down' ? N - 1 - t2 : line);
            var c2 = dir === 'left' ? t2 : (dir === 'right' ? N - 1 - t2 : line);
            if (board[r2 * N + c2] !== out[t2]) moved = true;
            board[r2 * N + c2] = out[t2];
          }
        }
        if (!moved) return;
        addTile();
        draw();
        if (!board.some(function (v) { return v === 0; }) && !canMove()) { over = true; api.lose(); }
      }

      function canMove() {
        for (var r = 0; r < N; r++) {
          for (var c2 = 0; c2 < N; c2++) {
            var v = board[r * N + c2];
            if (c2 + 1 < N && board[r * N + c2 + 1] === v) return true;
            if (r + 1 < N && board[(r + 1) * N + c2] === v) return true;
          }
        }
        return false;
      }

      function onKey(e) {
        var map = { ArrowUp: 'up', ArrowDown: 'down', ArrowLeft: 'left', ArrowRight: 'right', w: 'up', s: 'down', a: 'left', d: 'right' };
        var d = map[e.key];
        if (!d) return;
        e.preventDefault();
        slide(d);
      }
      window.addEventListener('keydown', onKey);
      pad.addEventListener('click', function (e) {
        var k = e.target && e.target.getAttribute && e.target.getAttribute('data-k');
        var map = { '↑': 'up', '↓': 'down', '←': 'left', '→': 'right' };
        if (k && map[k]) slide(map[k]);
      });

      addTile(); addTile(); draw();

      return function () { window.removeEventListener('keydown', onKey); };
    }
  });

