      var maxX = 0, maxY = 0;
      pos.forEach(function (p) { if (p.x + 1 > maxX) maxX = p.x + 1; if (p.y + 1 > maxY) maxY = p.y + 1; });
      var CELL = 100 / (maxX + 0.6);
      var CELLY = 100 / (maxY + 0.4);

      var box = el('div', 'stkbox');
      box.style.aspectRatio = (maxX + 0.6) + ' / ' + (maxY + 0.4);
      root.appendChild(box);

      var slotRow = el('div', 'slotrow');
      root.appendChild(slotRow);
      var slot = [];
      for (var q = 0; q < 7; q++) slotRow.appendChild(el('i'));

      var clearedV = api.hud('已消', '0 / ' + typeCount);
      var slotV = api.hud('卡槽', '0 / 7');
